/// <summary>
/// This class disable the update price lines popup
/// </summary>
[ExtensionOf(classStr(SalesTable2LineUpdatePrompt))]
internal final class METSalesTable2LineUpdatePrompt_Extension
{
}

Method.Source:
/// <summary>
/// This method prevents the update sales lines dialog form appearing
/// </summary>
/// <returns> true </returns>
public boolean extendedPrompt()
{
    SalesTable      salesTableLocal;
    SalesTable      salesTableEmpty;
    boolean         result;
    GUPParameters   gUPParameters = GUPParameters::find();

    if(gUPParameters.METSuppressPriceUpdate)
    {
        //making salesTable buffer empty
        salesTableLocal = this.salesTable;
        this.salesTable = salesTableEmpty;
    }
    result = next extendedPrompt();

    if(gUPParameters.METSuppressPriceUpdate)
    {
        this.salesTable = salesTableLocal;
    }

    return result;

}
